H={
'BESLUIT-Z3-WRIJ-056':("lege gangen van Ves-Anath in 610, waar alleen nog glas tinkelt","Een gezin dat in 610 weigerde te vertrekken, staat nergens in de ontruimingslijst.","legt het jaar van de ontruiming vast als ankerpunt voor fase 6"),
'BESLUIT-Z3-WRIJ-058':("een spiegel bij het eerste volwassen kaarslicht, en een teken dat er gisteren niet was","Een jonge vrouw van 18 ziet haar Bloedspiegel-ogen oplichten en weet dat haar register liegt.","verklaart waarom vervalsing loont tot de volwassenheid"),
'BESLUIT-Z3-WRIJ-059':("een bloedmerk dat na jaren nog vers ruikt, zonder rot","Een Hoedster meldt dat Liora's merk niet rot; de melding verdwijnt in een la.","maakt Liora's lichaam tot bewijs dat het Zegel zwak is"),
'BESLUIT-Z3-WRIJ-060':("de stem van een voorleesster die net iets anders voorleest dan er staat","De Registratrix van een blinde Moeder verandert één woord, en een huis verliest zijn erfgenaam.","geeft echte macht aan wie leest voor wie niet ziet"),
'BESLUIT-Z3-WRIJ-061':("grensdorpen waar opvallend veel mannen op het veld werken","Een inspectrice telt de grensmannen en past haar telling aan voor ze terugkeert.","houdt grensmannen als lokale uitzondering"),
'BESLUIT-Z3-WRIJ-062':("Karrûk-kampen met jongens tussen de krijgers","Een Karrûk-hoofdman weet niet dat zijn volk in zegelschaduw leeft; hij denkt dat zijn goden hem zegenen.","houdt de Karrûk-verhouding als lokale uitzondering"),
'BESLUIT-Z3-WRIJ-063':("de mosgeur van Aelthir-bossen en het zwijgen van wie ouder is dan de stad","Een Aelthir-oudste breekt bijna haar eed met de Makers wanneer de Orde haar bos laat kappen.","verklaart het zwijgen van de Aelthir"),
'BESLUIT-Z3-WRIJ-066':("het zware ademen van een reuzenstier in een te kleine stal","Een stalknecht ziet hoe de groei van een stier het lijf scheurt en noemt het een zegen om niet te huilen.","houdt grootte als body horror, zonder seksuele inhoud"),
'BESLUIT-Z3-WRIJ-067':("het geschreeuw van stallen in 612 die tegelijk stilvallen","Een overlevende van de stalopstand getuigt in 640 bij het Tribunaal.","legt de stalopstand vóór het Tribunaal in de tijdlijn"),
'BESLUIT-Z3-WRIJ-068':("het geknars van Glasbroeders die nog door lege zalen patrouilleren","De Glasbroeders laten Liora door omdat ze een oud bevel volgen dat de Orde vergeten is.","maakt het achterlaten van wachters een bewuste keuze van de Orde"),
'BESLUIT-Z3-WRIJ-073':("het koude zout van het Oevrin-slik waar eitjes in het water worden bevrucht","Een Orde-geleerde ontdekt dat het Zegel buiten de baarmoeder niets doet, en zwijgt.","verklaart waarom de Oevrin evenveel mannen hebben"),
'BESLUIT-Z3-WRIJ-078':("de lege blik van iemand in fase 3, die niet meer kan kiezen","Een priesteres die fase 3 toch in een rite gebruikt, wordt door haar eigen novice aangegeven.","legt vast dat er in fase 3 geen seks is"),
'BESLUIT-Z3-WRIJ-084':("een Ysa-lamp die flikkert en een rij vrouwen die knielen","Een lampenmaakster begrijpt dat het flikkeren meet, niet bidt.","maakt de lampen een verborgen lekdetector"),
'BESLUIT-Z3-WRIJ-099':("twee portretten met dezelfde naam, tweehonderd jaar uit elkaar","Een historica houdt de twee Moeders Iresse voor één, tot ze de handschriften vergelijkt.","lost de dubbele Iresse op als grootmoeder en kleindochter"),
'BESLUIT-Z3-WRIJ-104':("het eerste afkondigen van de Deelwet op een dorpsplein in 40","Ylva ziet Halvar in 45, midden in het verzet, en weet aan welke kant ze staat.","bevestigt de volgorde Deelwet, verzet, Ylva"),
'BESLUIT-Z3-WRIJ-106':("twee rijen pestgraven, één uit 340 en één uit 470","De Myrrhen zijn geboren uit de tweede Pest, en dragen haar sporen nog.","scheidt de twee pesten en verankert de Myrrhen"),
'BESLUIT-Z3-WRIJ-D1-1':("dertien manen op de muur van een tempel, met een lege dertiende boog in oude kalenders","Een oude kalender met twaalf maanden verraadt dat de Orde er later één bijvoegde.","legt de kalender vast op dertien maanden"),
'BESLUIT-Z3-WRIJ-D1-2':("een kleine, scherpe lichtsplinter aan een heldere hemel","Lirra Sterrenkijkster ziet de splinter op een avond van plaats veranderen.","geeft de hemel een tweede maan en een vraag"),
'BESLUIT-Z3-WRIJ-D1-3':("de grauwe as in het brood van de Orde-asgang","Een Aelthir weigert het brood en wordt verdacht, want zij weet wat erin zit.","maakt het asbrood bewust tot verhaalbron"),
'BESLUIT-Z4-fasen':("de lange stenen rij van fasemerken in de Hoge Tempel","Elk volk vertelt dezelfde fase anders; de verschillen wijzen naar wat verborgen is.","legt de volgorde van de tijdlijn vast"),
'BESLUIT-Z4-liora':("hooi, aarde en de kou van Hallowyn op een boerendochter van 25","Iedere partij wil Liora omdat ze nergens bij hoort, en zij merkt dat als eerste.","maakt Liora de ogen van de lezer en de sleutel van de derde weg"),
'BESLUIT-Z4-mannenraad':("een kleine kamer waar mannen voor het eerst samen spreken, met de deur op slot","De Mannenraad krijgt één stem in de Raad, en beide machten willen die stem kopen.","houdt de opkomst van mannen laat en duur"),
'BESLUIT-Z4-nietmens':("veertien manieren van rekenen, ruiken en tellen","Twee volken lezen hetzelfde verdrag en begrijpen het tegenovergestelde.","geeft elk volk een eigen verhaal naast de hoofdlijn"),
'BESLUIT-Z4-plekken':("de geur van elke regio op de route: zout, hooi, rook, mos","Op de route van boek 1 ligt één plek die niet op de kaart staat.","geeft de wereld genoeg plekken om scènes te dragen"),
'BESLUIT-Z4-prequel':("het rode alarmlicht in de gangen van Ysa tijdens de stemming","De vijfde stem werd uitgebracht door iemand die het verraad had gezien.","maakt van het begin een muiterij die boek 1 dramatische ironie geeft"),
'BESLUIT-Z4-skelet':("een tijdlijn als een ruggengraat van ruim tachtig wervels","Een gat in het skelet blijkt een opzettelijk weggelaten gebeurtenis.","houdt het skelet vast en uitbreidbaar"),
'BESLUIT-Z4-ster':("een ster die beweegt en een signaal dat in tellen komt","Lirra telt dezelfde reeks drie nachten achter elkaar en schrijft die op.","geeft de reeks een lange, verborgen sciencefictionboog"),
'BESLUIT-Z4-volken':("veertien stemmen die elk een andere waarheid vertellen","Wie de lezer vertrouwt, hangt af van wiens ogen hij leent; één hoofdpersoon liegt.","geeft elk volk een hoofdpersoon"),
'BESLUIT-Z5-buitenstaanders':("Tamsins handen vol modder van Tharn-dijken, en Tobins Oevrin-zout op de huid","Een buitenstaander verandert haar gastvolk meer dan iemand met het juiste bloed.","legt vast dat wie het volk verandert, bij de keten hoort"),
'BESLUIT-Z5-makers':("Makersmetaal dat bij elk volk anders roest","Een Kluwer en een Aelthir ontdekken dat hun Maker dezelfde persoon was: schepper voor de één, voorouder voor de ander.","geeft elk volk een tweeledige band met de Makers"),
'BESLUIT-Z6-VRAAG-001':("een kraamkamer waar 99 meisjes huilen voor één jongen","Een geleerde berekent dat de verhouding verschuift zodra het Zegel verzwakt, en dat wordt een staatsgeheim.","maakt schaarste de motor van alle politiek"),
'BESLUIT-Z6-VRAAG-002':("de stille gloed van vonkcellen onder een Makers-lens","Een godsdienstige ziet de cellen onder de lens en verliest haar geloof.","maakt het geloof een vervalsing die ontmaskerd kan worden"),
'BESLUIT-Z6-VRAAG-003':("het bevel van de Raad der Moeders, opgenomen in de scheepslogs van jaar 0","Een log bewijst dat mensen de Stille Modus aanzetten, niet de goden.","legt de schuld bij mensen"),
'BESLUIT-Z6-VRAAG-005':("het heilige woord dat in een stille kamer valt, en de rang die daarna wegglijdt","Een vrouw die weigert, verliest haar zaadrecht en wint iets wat niet in het register staat.","geeft elke weigering een prijs en dus een verhaal"),
'BESLUIT-Z6-VRAAG-006':("de spanning in een kraamkamer waar een gewone vader op een jongen wacht","Een zoon van een gewone man blijkt een vonk te hebben, en drie huizen willen hem.","laat huizen op bloedlijnen jagen"),
'BESLUIT-Z6-VRAAG-007':("de warmte van de Wortel als Liora dichterbij komt","Het Zegel wil kiezen, maar het wil ook Liora houden.","maakt de queeste een keuze, geen vernietiging"),
'BESLUIT-Z6-VRAAG-008':("andere wetten bij elke grenspaal, voor dezelfde man","Een man die in de ene regio vrij is, wordt bij de volgende brug bezit.","maakt elke reis een rechtsreis"),
'BESLUIT-Z6-VRAAG-010':("het tellen van uren na een Ontvangst, kracht die wegebt als een getij","Een gaven-man die twee keer per dag moet geven, wordt elke keer zwakker en duurder.","maakt tijd per nacht tot intrige"),
'BESLUIT-Z6-VRAAG-011':("een kruik die binnen het uur afkoelt en waardeloos wordt","Een koerierster rent met een kruik door de stad en heeft nog tien minuten.","maakt zaadhandel een race tegen de klok"),
'BESLUIT-Z6-WRIJ-049':("het zachte zoemen van dragers in de Wortels, die het Zegel voeden zonder seksuele rol","Een moeder vindt haar zegelgeboren zoon terug als drager en kan hem niet wekken.","legt vast waar de zegelgeborenen blijven"),
'BESLUIT-Z6-WRIJ-052':("rook boven de havenwijk van Lisk en zout water dat de vlammen niet dooft","De overlevenden van de havenbrand gaan naar de Zusters, en dat maakt de Zusters groot.","verklaart een brand die het geloof versterkte"),
'BESLUIT-Z6-WRIJ-064':("zoutpaden langs Grauwend, waar voetstappen snel dichtwaaien","Een volwassen zegelgeborene vlucht tijdens de overplaatsing naar de Wortels, en de Vathren wachten.","verklaart hoe de Vathren aan mensen komen"),
'BESLUIT-Z6-WRIJ-065':("grijze, schilferende huid van een askoude die alles helder ziet","Een askoude kent de weg naar een kluis, en vraagt geen geld maar een herinnering.","maakt de askouden zeldzaam en waardevol als gids"),
'BESLUIT-Z6-WRIJ-069':("Liora's handen die niet branden aan heet zegelglas","Liora pakt een gloeiende scherf vast en een Ishvar herkent het als familie.","verklaart Liora's hittebestendigheid via Grieta's moeder"),
'BESLUIT-Z6-WRIJ-070':("een belastingrol met de aantekening 'vrijgesteld, kinderloos paar'","Een Dhurn-paar van twee mannen wordt beloond, en hun buren worden jaloers.","laat zien hoe het systeem kinderloosheid beloont"),
'BESLUIT-Z6-WRIJ-071':("de korte mannelijke fase van een Ves-Lethi, als een seizoen dat te snel voorbij is","Een huis koopt een Ves-Lethi-man en ontdekt dat zijn zaad geen kracht geeft.","maakt Ves-Lethi waardeloos voor de krachteconomie en waardevol voor iets anders"),
'BESLUIT-Z6-WRIJ-072':("de vochtige zwamgrotten waar een zwangere vrouw maanden woont","Een vrouw verstopt zich in de grotten om haar zoon te beschermen, en de Orde zoekt haar.","beperkt de werking van de zwam tot haar mycelium"),
'BESLUIT-Z6-WRIJ-075':("de zeldzame 10 op de walgingsschaal, bij de vleesbrug van Ves-Anath","Een lezer die alles al gezien denkt te hebben, ziet de vleesbrug.","houdt de top van de schaal zeldzaam"),
'BESLUIT-Z6-WRIJ-077':("een gelofte in oud schrift, die iemand bindt die al jaren niet meer kan kiezen","Een advocate bouwt een zaak tegen de voorinstemming op die het Lichtconvent later kan dragen.","houdt de hypocrisie van de Orde zichtbaar en geeft haar een oplossing in een latere tijd"),
'BESLUIT-Z6-WRIJ-079':("de geur van Ankerwortel: Grijswortel, maar zoeter en zwaarder","Een kruidster herkent de kweekvariant en weet dat haar eigen Orde haar recept stal.","maakt Ankerwortel het spiegelbeeld van Grijswortel"),
'BESLUIT-Z6-WRIJ-081':("het schrille krassen van een registerkraai die een verkeerde naam roept","Teo staat als Lijngraver in de boeken door een vergissing van een vogel.","maakt Teo's lot toeval in plaats van bloed"),
'BESLUIT-Z6-WRIJ-082':("de holle stem van een gaven-man die zegt dat hij god is","Morvane-ir draait de leer om: hij 'eet de god op' en noemt dat heiligheid.","geeft de ketterij een woord om mee te vechten"),
'BESLUIT-Z6-WRIJ-083':("zegeltol in rijen munten in Varennes kluis, veertig jaar opgespaard","Varenne laat de schuld liever openstaan dan haar te innen.","maakt schuld een machtsmiddel"),
'BESLUIT-Z6-WRIJ-085':("Ishvar-handen die zegelsteen dragen zonder te gloeien","Een Ishvar smokkelt zegelsteen voor Qesh en voor de Orde tegelijk.","verklaart waarom een theocratie goddelozen beschermt"),
'BESLUIT-Z6-WRIJ-087':("as van verbrande brieven in Grieta's haard","Grieta wist het al die tijd, en verbrandde het bewijs voor Liora's bestwil.","verbindt Grieta's twee afkomsten"),
'BESLUIT-Z6-WRIJ-088':("de lege regel 'onbekende vader' in het register van Saelith","Iska's zoon wordt 25 en is het levende bewijs dat Ves-Lethi kinderen kunnen verwekken.","levert een verborgen erfgenaam"),
'BESLUIT-Z6-WRIJ-089':("koude correspondentie tussen Orde en Kaldra, beleefd en vol dreiging","Kaldra heeft een tweede verborgen gaven-man, en de Orde weet zijn naam niet.","geeft een koude oorlog van chantage"),
'BESLUIT-Z6-WRIJ-090':("tribunaalverslagen met inktvlekken op de lekjaren","Een advocate legt de data van vonnissen naast de lekjaren en ziet het patroon.","maakt de rechtspraak het bewijs van de lekken"),
'BESLUIT-Z6-WRIJ-091':("de stem van een stemvrouw die woorden van een man herhaalt","Teo moet een vrouw vinden die zijn waarheid wil dragen, en zij loopt daarmee een risico.","geeft mannen een stem via een ander"),
'BESLUIT-Z6-WRIJ-093':("papieren die de fase van een graver altijd net te laag noteren","Een Lijngraver eist zijn fase-1-recht en ontdekt dat hij op papier nooit fase 1 bereikte.","laat zien hoe recht op papier wordt omzeild"),
'BESLUIT-Z6-WRIJ-095':("hete grond rond de gevallen kernhelft en botten die de weg markeren","Wie het Ishvar-kamp bereikt zonder Ishvar te zijn, verbrandt; één vrouw overleeft.","maakt het kamp een plek die alleen Ishvar halen"),
'BESLUIT-Z6-WRIJ-096':("drie klokken die in de Bloedmaan na elkaar luiden","Drie deadlines in een week: crisis, zegelbinding en de Lege Dag.","geeft de climax een strak tijdschema"),
'BESLUIT-Z6-WRIJ-100':("inkt op de vingers van een oude marktschrijfster","Annike herkent Liora's blad omdat ze het zelf vervalste.","maakt een marktschrijfster de sleutel tot Liora's afkomst"),
}
